import argparse
from pathlib import Path

BITMAPS_DIR = Path(__file__).resolve().parent / "bitmaps"
EXEC_PREFIX = "exec"
BITS_PER_BYTE = 8

def create_header(file_name):
    return [
        "/************************************************************************",
        f"* @file {file_name}",
        "*",
        "* @brief Generated by interface/assets/gen_assets.py from interface/assets/bitmaps/.",
        "* @note Do not edit, change the art and rebuild.",
        "* @author João Matheus Nascimento Dias (joao.dias@edge.ufal.br)",
        "* @version 0.1",
        "* @date 27/10/2026",
        "*",
        "* @copyright Centro de Inovação EDGE 2026. Todos os direitos reservados.",
        "*",
        "***********************************************************************/",
        "",
    ]

def parse(path):
    directives, rows = {}, []
    allowed_chars = set(".#123456789")
    
    for index, line in enumerate(path.read_text().splitlines(), 1):
        if line.startswith(EXEC_PREFIX):
            key, _, value = line[len(EXEC_PREFIX):].strip().partition(" ")
            directives[key] = value.strip()
        elif line:
            if set(line) - allowed_chars:
                raise SystemExit(f"{path.name}:{index}: only '.', '#' and 1-9 are allowed")
            rows.append(line)
            
    if not rows or any(len(row) != len(rows[0]) for row in rows):
        raise SystemExit(f"{path.name}: every row must have the same width")
    
    return directives, rows


def lit(rows, level=None):
    width = len(rows[0])
    
    return [
        ["#" if char == "#" or (char.isdigit() and (level is None or int(char) <= level
                                               or min(col, width - 1 - col) % 2 == 0))
         else "." for col, char in enumerate(row)] for row in rows
    ]


def slashed(rows):
    rows = [row[:] for row in rows]
    height, width = len(rows), len(rows[0])
    diagonal_cols = [round(row_idx * (width - 1) / (height - 1)) for row_idx in range(height)]

    for row_idx, col_idx in enumerate(diagonal_cols):
        for col_offset in (-1, 1):
            if 0 <= col_idx + col_offset < width:
                rows[row_idx][col_idx + col_offset] = "."

    for row_idx, col_idx in enumerate(diagonal_cols):
        rows[row_idx][col_idx] = "#"

    return rows


def to_bytes(rows):
    bytes_per_row = (len(rows[0]) + BITS_PER_BYTE - 1) // BITS_PER_BYTE
    output_bytes = []

    for row in rows:
        bit_string = "".join(row).replace("#", "1").replace(".", "0")
        padded_bits = bit_string.ljust(bytes_per_row * BITS_PER_BYTE, "0")
        output_bytes += [int(padded_bits[offset:offset + BITS_PER_BYTE], 2)
                         for offset in range(0, len(padded_bits), BITS_PER_BYTE)]

    return output_bytes


def collect():
    bitmaps = []
    
    for bitmap_path in sorted(BITMAPS_DIR.glob("*.txt")):
        bitmap_name = bitmap_path.stem
        directives, rows = parse(bitmap_path)
        
        brief = directives.get("brief", f"{bitmap_name} bitmap")
        max_level = max((int(char) for row in rows for char in row if char.isdigit()), default=0)

        symbols = [(f"zbook_{bitmap_name}", brief, to_bytes(lit(rows)))]
        
        if max_level:
            for level in range(max_level + 1):
                symbols.append((
                    f"zbook_{bitmap_name}_level_{level}",
                    f"{brief}, level {level} of {max_level}",
                    to_bytes(lit(rows, level)),
                ))
                
        if "slashed" in directives:
            symbols.append((
                f"zbook_{bitmap_name}_off",
                f"{brief}, slashed",
                to_bytes(slashed(lit(rows))),
            ))

        width = len(rows[0])
        height = len(rows)
        bitmaps.append((f"ZBOOK_{bitmap_name.upper()}", width, height, symbols))
    return bitmaps


def render_h(bitmaps):
    lines = create_header("assets.h") + [
        "#ifndef ZBOOK_ASSETS_H",
        "#define ZBOOK_ASSETS_H",
        "",
        "#include <stdint.h>",
        "",
        "#ifdef __cplusplus",
        'extern "C" {',
        "#endif",
        "",
    ]
    
    for macro_prefix, width, height, symbols in bitmaps:
        symbol_names = ", ".join(symbol for symbol, _, _ in symbols)
        lines += [
            f"/**\n* @brief Width of {symbol_names}, in pixels.\n*\n*/",
            f"#define {macro_prefix}_W {width}",
            f"\n/**\n* @brief Height of {symbol_names}, in pixels.\n*\n*/",
            f"#define {macro_prefix}_H {height}",
            "",
        ]
        
        for symbol, description, _ in symbols:
            lines += [
                f"\n/**\n* @brief {description}, {width}x{height}, row major, MSB first, 1 bit per pixel.\n*\n*/",
                f"extern const uint8_t {symbol}[];",
            ]
        lines.append("")
        
    lines += ["#ifdef __cplusplus", "}", "#endif", "", "#endif /* ZBOOK_ASSETS_H */", ""]
    
    return "\n".join(lines)


def render_c(bitmaps):
    lines = create_header("assets.c") + ['#include "actuator/assets/assets.h"', ""]
    
    for _, _, _, symbols in bitmaps:
        for symbol, _, byte_values in symbols:
            lines.append(f"const uint8_t {symbol}[] = {{")
            
            for offset in range(0, len(byte_values), BITS_PER_BYTE):
                lines.append("\t" + " ".join(
                    f"0x{value:02x}," for value in byte_values[offset:offset + BITS_PER_BYTE]
                ))
                
            lines += ["};", ""]
            
    return "\n".join(lines)


def write_if_changed(path, content):
    if not path.exists() or path.read_text() != content:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content)


def main():
    parser = argparse.ArgumentParser(description="Generates the ZBook display assets.")
    parser.add_argument("--out-dir", required=True, type=Path,
                        help="writes <dir>/assets.c and <dir>/include/actuator/assets/assets.h")
    args = parser.parse_args()

    bitmaps = collect()
    write_if_changed(args.out_dir / "include" / "actuator" / "assets" / "assets.h",
                     render_h(bitmaps))
    write_if_changed(args.out_dir / "assets.c", render_c(bitmaps))


if __name__ == "__main__":
    main()
